insert into public.passage_prompts (book, chapter, prompt) values ('2 Chronicles', 26, 'Uzziah prospered greatly as long as he sought God''s guidance, but when he grew strong, he overstepped into territory that wasn''t his and refused correction. Where in your own life or marriage do you sense the pull to take control of something that isn''t yours to control?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Chronicles', 27, 'Jotham became mighty by ordering his ways before God, yet the people around him still acted corruptly. Where do you each see yourself trying to live faithfully while those close to you move differently, and how is that working out between you?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Chronicles', 29, 'When you each look at the mess that needs cleaning in your own life or marriage, what holds you back from calling on your people to help you tackle it together, the way Hezekiah did?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Chronicles', 30, 'When Hezekiah invited people from far away to gather together, some mocked the invitation while others came. As you think about your own life, when have you felt pulled to move toward something good even when it seemed difficult or when others weren''t doing the same?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Chronicles', 31, 'As you both look at what Hezekiah built, systems and structures so people could give generously and serve faithfully, where do you each sense God calling you to organize your own life or marriage differently?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Chronicles', 32, 'When Hezekiah faced Sennacherib''s threats, he first prepared the walls and gathered weapons, then gathered the people to speak encouragement about God''s help. Where do you each tend to start when you face something that frightens you together, and how does that shape what happens next?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Chronicles', 33, 'When you each look at how Manasseh returned to what was right after his time of trouble, what in your own marriage or life have you had to rebuild or set right after going the wrong direction?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Chronicles', 34, 'Josiah discovered the book of the law and immediately responded by humbling himself and gathering everyone to hear it read together. What truth about God or your marriage have you each been ignoring or overlooking, and what might change if you faced it together this week?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Chronicles', 35, 'Josiah prepared everyone carefully for the Passover, enlisting people across different roles and even having others serve so no one had to leave their post. Where in your own life together do you need that kind of purposeful preparation and coordination, rather than hoping things will just work out?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Chronicles', 36, 'In this chapter, Zedekiah refused to humble himself when the prophet spoke, and stiffened his neck against turning back to God. When you both face a hard truth or difficult correction, what makes it easier or harder for each of you to stay open rather than close off?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Kings', 1, 'When you''re facing uncertainty or illness, where do you each naturally turn first for help or answers, and what does that reveal about what you''re trusting in that moment?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Kings', 2, 'Elisha refused to leave Elijah''s side even when given permission, and later grieved deeply at the loss. When have you each held on to something or someone important, and what did that cost you both?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Kings', 3, 'When you each face a difficult situation this week, will you be more like the king of Israel who despaired, or like Jehoshaphat who looked for godly counsel?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Kings', 4, 'When the widow and the Shunammite woman each faced a crisis, they both took immediate action to seek help, yet their stories turned out very differently. What kinds of problems do you each tend to bring to each other right away, and which ones do you tend to handle alone first?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Kings', 5, 'When you each think about the servants in this story, the little maiden who spoke up for Naaman, his own men who gently corrected him, and Gehazi who chose differently, whose example feels most alive to you right now, and why?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Kings', 6, 'When fear or crisis hits your household, how do you each tend to respond, and do you help each other look beyond the immediate panic to what might still be true?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Kings', 7, 'The four lepers chose to risk their lives by going to the Syrian camp because staying put meant death either way. When have you both faced a situation where doing nothing felt as dangerous as taking a leap, and how did you move forward together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Kings', 8, 'The Shunnamite woman had to leave everything behind for seven years on a word from the prophet, then came back to reclaim what was hers. When has each of you had to act on faith before seeing how things would work out, and how did that trust change you?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Kings', 9, 'When you each consider a time you''ve had to act on something you believed was true but couldn''t fully prove to others yet, what made you move forward, and what made you hesitate?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Kings', 10, 'As you watch Jehu do the right thing in one way but hold back in another, what area of your own faith or your marriage calls you to full commitment rather than partial obedience?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Kings', 12, 'When you both think about something you''ve committed to fixing or improving together, what gets in the way of actually doing it, and what would help you get unstuck like Jehoash eventually did?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Kings', 13, 'When you''ve begged God for help and received it, have you found yourself still holding onto the old patterns you asked to be freed from, the way Israel did after their deliverance?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Kings', 14, 'When you''ve had a victory or success, how do you each tend to respond: do you stay grounded and seek wise counsel, or does confidence sometimes carry you past the warnings of people who care about you?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Kings', 15, 'Both Azariah and Jotham did what was right, yet the high places were never removed and the people kept offering sacrifices there. When have you and your spouse done something good but left something important unfinished, and what would change if you addressed it together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Kings', 16, 'When you face a threat or crisis, do you find yourself reaching for something or someone outside your core values to feel secure, and what does that cost you both?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Kings', 17, 'When you look at how Israel kept picking up the practices of the nations around them instead of following what they''d been told, where do you each notice that happening in your own lives or in your marriage?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Kings', 18, 'When you hear voices telling you to doubt what you trust in, how do you decide what''s worth holding onto between now and when you see how things actually turn out?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Kings', 19, 'When you each face something that feels threatening or impossible this week, what does it look like for you to bring it before God together, the way Hezekiah spread that letter before him?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Kings', 20, 'When you each learned about Hezekiah''s healing, he then immediately showed the Babylonian envoys everything he treasured and owned, only to hear that it would all be taken away. What do you hold most tightly to right now, and how might that affect how you see your future together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Kings', 21, 'When you look at the choices each of you made this week, where did one of you follow a pattern from someone else rather than thinking it through yourselves?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Kings', 22, 'When you each discovered something about your life or marriage that needed changing, how did you respond in that first moment, and what made the difference between turning away or turning toward it?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Kings', 23, 'As Josiah pulled away from what had become comfortable or familiar in his life, what holds your grip most strongly right now, and how might each of you be called to release it together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Kings', 24, 'When you each look at how Jehoiakim, then Jehoiachin, then Zedekiah all followed the same path despite seeing what happened to the king before them, what pattern do you recognize in your own lives, and how do you help each other break it?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Kings', 25, 'After a season of destruction and loss, Gedaliah offers the frightened survivors a way to stay and rebuild, yet fear drives them to flee anyway. Where do you both tend to run when you''re afraid, and what would it take for you to trust and stay?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Samuel', 1, 'When you each learned this news about Saul and Jonathan, what moved David more, the loss of a rival, or the loss of someone he loved, and how does that distinction speak to what you each value in your own relationships?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Samuel', 2, 'When you each read about David seeking direction from God before moving to Hebron, and then about how quickly things turned violent between his forces and Saul''s, what does it stir in you about asking for guidance together in moments when the path ahead feels uncertain?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Samuel', 3, 'David grieves publicly over Abner''s death, even though Abner had been working against him, and the people notice how he handles this loss. When you each face something unjust in your marriage or life, how do you want the other person to see you respond?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Samuel', 4, 'When Rechab and Baanah brought David what they thought he wanted, he rejected it and punished them for it. What have you each ever done for your spouse thinking you were helping, only to discover they didn''t want it that way at all?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Samuel', 6, 'When David danced unselfconsciously before God while Michal watched and judged him, what does that reveal about where each of you finds freedom, and where you might feel more concerned with how others see you than with what matters most?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Samuel', 7, 'David had rested from his enemies and wanted to build something grand for God, but God redirected his plans toward a different kind of legacy. When have you both felt called to do something good, only to discover God had something else in mind for you?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Samuel', 8, 'As you each read how David dedicated all the plunder and treasures from his victories to the Lord, what are you holding onto right now that might be asking to be given back to him?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Samuel', 10, 'When have you each misjudged someone''s kindness or good intentions, and how did you find your way back to trust?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Samuel', 11, 'When have you each hidden something from the other, or found yourselves unable to stop a wrong choice once it started, and what finally turned things around?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Samuel', 12, 'When you saw yourselves reflected in Nathan''s story, what was that moment like, and what does it change between you now that you''ve both acknowledged it?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Samuel', 13, 'When you each think about times you''ve been angry with someone close to you, how long have you let that anger grow before it changed who you are?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Samuel', 14, 'When you read about the king finally reconciling with Absalom, what unfinished business between the two of you comes to mind, and what would it take for you each to move toward healing in that area?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Samuel', 15, 'When you look at how Absalom won people over with his charm and attention, while you''ve felt neglected or unseen, where do you recognize that pattern playing out between you?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Samuel', 16, 'When David is insulted and attacked, he chooses not to retaliate, sensing that God may be using even this curse for some purpose; where in your own conflict or disappointment this week might you be tempted to strike back, and what if you didn''t?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Samuel', 17, 'When you each read how people around David gave him counsel, some meant to harm him, some to help, whose voice do you most often turn to when you''re facing a difficult decision together, and is that the wisest counsel you could be hearing?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Samuel', 18, 'David loved his son Absalom even after Absalom turned against him. When you think about the people in your life who have hurt you or disappointed you, how do you each hold both your anger and your love at the same time?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Samuel', 19, 'When you see David moved to action not by his own grief but by Joab''s words about those who stood by him, what situation in your own lives comes to mind where you needed to set aside something weighing on you to acknowledge someone else''s faithfulness?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Samuel', 20, 'When have you each seen a moment of conflict resolved not by force, but by someone willing to speak wisdom into the situation, the way the woman of Abel did? What made that person''s voice heard when others weren''t listening?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Samuel', 21, 'When you read about Rizpah''s faithfulness to those she loved, even in grief, what kind of loyalty do you most need from each other right now?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Samuel', 22, 'David sings this song after being delivered from enemies who were too mighty for him, and he celebrates how God made his way perfect. When you look back at a hard time you''ve recently faced together, where did you each sense God''s strength showing up in ways you couldn''t manage on your own?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Samuel', 23, 'David refused to drink the water his men risked their lives to bring him, pouring it out instead as an offering to God. When have each of you sacrificed something or held back from taking what you wanted, and what was that choice rooted in?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('2 Samuel', 24, 'When you recognize a mistake, like David did, do you tend to make things right on your own, or do you wait for someone else to point the way, and how does that show up between you two?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Colossians', 3, 'When you think about what you''re angry about or holding against each other this week, what would it look like to forgive the way the chapter describes, and what''s making that hard for you both right now?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Daniel', 5, 'Belshazzar knew what happened to his father when pride took over, yet he didn''t change course. Where do each of you see yourselves repeating patterns you''ve watched others experience, and how might you help each other break that cycle?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Daniel', 6, 'When have you each faced a moment where doing what was right conflicted with what was easier or safer, and how did you handle it together or separately?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 1, 'When you both look back at times you''ve faced something that frightened you, how did fear shape what you actually did, and where do you wish you had trusted more?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 2, 'When has God shown you restraint was the right choice, and when have you seen Him make way for something new instead?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 3, 'When you look at what God has asked each of you to do in this season, are there parts you''re at peace with accepting, and parts where you''re still wrestling with how things turned out?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 4, 'As you both think about what God has done for you together, what is something from your past that you might be tempted to forget, and how can you help each other remember it?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 5, 'As you read these commandments together, which one calls you to look most honestly at your own life right now, and what would it take for each of you to keep it more faithfully this week?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 6, 'When you''re blessed with something good in your life, how do you each tend to remember where it came from, and where might you need to remind each other?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 7, 'The passage warns against being drawn away by the gods and ways of those around you, and speaks of keeping yourself set apart. What distractions or influences in your current life feel most likely to pull each of you away from what matters most to you both?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 8, 'As you each think about a time when things became easier or more abundant in your life, did you notice yourselves drawing closer to God or drifting away, and what made the difference?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 9, 'Moses keeps reminding the people that they did not earn what God is giving them, that they have been stiff-necked and rebellious from the start. Where in your own lives do you find it hard to receive something good without feeling like you had to deserve it first?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 10, 'Moses says God requires you to walk in all his ways, love him, and serve him with all your heart, and then he speaks especially about loving the foreigner and caring for those who are vulnerable. As you think about your week ahead together, where might you both need to soften a resistant heart toward someone God is calling you to serve?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 11, 'When you think about what you''re keeping before your eyes and hearts these days, what you talk about in your home, what you''re teaching each other by your daily choices, is it drawing you closer together toward what you both believe, or drifting in another direction?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 12, 'This chapter calls the people together to worship and celebrate at one chosen place, and emphasizes eating, rejoicing, and including others in that celebration. Where do you both find yourselves gathering and sharing as a couple, and who else do you invite into those times?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 13, 'When someone close to you, a family member, friend, or trusted voice, has pulled you away from what you know to be true, how did you each respond, and what brought you back?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 15, 'When you think about money and help in your own life right now, where do you find yourself holding back, and what would it look like to open your hand instead?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 16, 'When this chapter calls you to remember being slaves and to rejoice together while including the vulnerable among you, what does it stir in how you want to show up for each other and those around you this week?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 17, 'When you each face a decision that feels too hard to navigate alone, do you turn toward wise counsel, or do you tend to figure it out by yourselves?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 18, 'The passage talks about those set apart to serve God and warns against seeking guidance from other sources instead. Where do you each turn when you need direction in life, and how does that show what you''re really trusting?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 19, 'When you think about how quickly things can go wrong by accident, where do you each need more patience or grace toward one another this week?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 20, 'When you face something that feels overwhelming or bigger than you, what helps each of you remember that you''re not alone in it?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 21, 'When you read about how the community took responsibility for bloodshed, or how fairness required honoring the firstborn even when he wasn''t favored, what situation in your own life came to mind where doing what''s right might cost you something?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 22, 'When you read about someone finding a lost animal and bringing it home, what does that picture bring to mind about how you and your spouse handle each other''s struggles or needs when they''re not immediately obvious?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 23, 'When you think about the vows or promises you''ve made to each other and to God, do you both feel at peace with how you''re keeping them, or is there something either of you has been putting off?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 24, 'This chapter shows a husband given a full year free from work and duty to spend with his new wife, yet also lays out hard rules about pledges, wages, and care for the vulnerable, as if daily life demands both tenderness and justice. Where do you each feel pulled between giving your full attention to one another and the many obligations pressing on your time?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 25, 'When you think about the ways you''ve been dishonest or taken shortcuts in your marriage or life this week, what has made it hard to choose the difficult path of being straightforward instead?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 26, 'When you bring the first of what you''ve grown or earned to God, what story do you tell yourself about how you got there, and does that story change what you do with what remains?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 27, 'As you listen to these curses read aloud, each naming specific wrongs the people promise to reject together, what is one way you have recently supported each other in staying true to something that matters to both of you?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 28, 'When you hear this chapter describe both blessing and hardship flowing from whether people listen or turn away, what are you currently listening to in your own life, and how is that shaping what''s unfolding between you?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 29, 'As you stand together in your own covenant, your marriage, what has God shown you and sustained you through that you''re tempted to forget or take for granted?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 30, 'When you think about the choice between life and death, blessing and curse that Moses sets before the people, what choice are you each actually making this week in how you live together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 31, 'Moses prepares his people for his death by repeatedly calling them to be strong and courageous, yet he also warns them that they will turn away from God. As you both think about the transitions and changes ahead in your own lives, where do you find yourselves needing courage, and where might you be drifting without realizing it?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 32, 'The song describes how God sustained the people abundantly, yet they forgot him in their comfort and turned away. Where do you each see comfort tempting you to drift from what matters most, and how might you help each other notice it?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Deuteronomy', 33, 'As you hear Moses blessing each tribe for their different strengths and paths, what particular gifts or callings do you each see in the other that you want to speak out loud?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Ecclesiastes', 1, 'When you look at your own week, what have you been pouring energy into that hasn''t quite filled the emptiness you hoped it would?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Ecclesiastes', 2, 'When you look at what you''ve built together, your home, your routines, your accomplishments, do you find yourself enjoying them as gifts, or does anxiety about losing them or leaving them behind creep in?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Ecclesiastes', 3, 'When you look at this past season of your life together, what felt like a time for planting or building, and what felt like a time for pulling up or breaking down, and how did you each find joy in both?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Ecclesiastes', 4, 'When you think about the work you both do and the life you''re building together, are you laboring toward something that actually satisfies you, or chasing after things that leave you empty?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Ecclesiastes', 5, 'When you look at what you''ve promised to each other or to God, are there any commitments you''ve made but let slip, and what would it take to honor them again?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Ecclesiastes', 6, 'When you each think about what you''re spending your energy chasing this week, does it feel like it''s truly nourishing you, or does it sometimes feel hollow even when you get what you''re after?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Ecclesiastes', 7, 'This chapter keeps pulling you toward hard truths, that sorrow can teach you more than laughter, that patience matters more than pride, that nobody gets it all right, so where in your own life this week have you felt yourself learning something through difficulty rather than ease?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Ecclesiastes', 8, 'When you look at your own week, where have you seen wisdom actually change how something went, and where have you felt the weight of things beyond your control?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Ecclesiastes', 9, 'The teacher in this chapter urges you to eat with joy and live joyfully with the one you love, while also accepting that much of life is beyond your control. Where do you each sense you''re holding back from simple joy together because you''re waiting for something else to be settled first?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Ecclesiastes', 10, 'When you each think about a small careless choice you made this week, how did it ripple out in ways you didn''t expect, and what does that tell you both about the value of paying attention?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Ecclesiastes', 11, 'When you think about all the uncertainty ahead of you both, what''s one thing you keep doing anyway, and what''s one thing fear keeps you from trying?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Ecclesiastes', 12, 'As you both think about remembering your Creator while you''re young and able, what are one or two things you want to make sure matter most between now and then?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Ephesians', 4, 'When the passage describes putting away the old way and being renewed in mind, where do you each see that renewal happening, or being resisted, in your own life together this week?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Ephesians', 5, 'Where in your daily life together do you each need to ''watch carefully how you walk,'' and what would it look like for you both to help each other stay awake to what matters most?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 1, 'When have you each felt caught between an unjust demand and your own conscience, and how did you support each other through that choice?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 2, 'Moses moved from one family to another, from danger to safety, and eventually built a new life with Zipporah. When you think about the transitions or upheavals in your own marriage, how have you each found ways to help and trust one another through them?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 3, 'When God told Moses he would send him to free the people, Moses asked ''Who am I?'' instead of ''I''m afraid'' or ''I can''t.'' What hesitation or doubt are each of you sitting with right now, and how might naming it together change how you see it?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 4, 'When you''ve been afraid you weren''t enough for something God asked of you, how did he actually provide what you needed, and what did that teach you about partnership between the two of you?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 5, 'When you''ve asked for something important and it made things harder instead of better, how did you each handle the disappointment and doubt that followed?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 6, 'God tells Moses he has heard the groaning of the people and remembered his covenant, yet when Moses shares this promise, the Israelites won''t listen because of their suffering and exhaustion. Where do you each sense that kind of weariness in your own life right now, and how might you help carry each other through it?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 7, 'When you''ve felt certain about what God was asking of you, have you each experienced resistance or doubt, even after seeing something work out? How do you both keep going?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 8, 'When Pharaoh promises to let the people go but then changes his mind once relief comes, where do you each notice yourselves making similar promises in your own marriage that slip away once the pressure eases?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 9, 'When Pharaoh saw the destruction stop, he went back on his word instead of letting the people go, each of you: what promises to each other have you found hardest to keep when the pressure eased?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 10, 'When Moses insisted on taking everything, the young and old, flocks and herds, all that was needed to worship, he refused to leave anything behind; when you both think about what you''re holding back from God or from serving him together, what comes to mind?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 11, 'As you listen to Moses describe what God will do to finally free his people, what feels impossible or too hard in your own lives right now that you''re waiting for God to move on?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 12, 'When you think about the Israelites being told to stay inside their homes with their doors marked until morning, what makes you feel most secure or most anxious in your own life together right now?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 13, 'When you look back at how God has guided you through a difficult time, what signs or practices help each of you remember and tell that story to others?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 14, 'When you each face something that feels impossible this week, what would it look like for you to ''stand still'' together instead of panic, the way Moses asked the frightened people to do?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 15, 'You both just celebrated a miraculous deliverance, and now three days later you''re facing bitter water and doubt. When has something you thought was settled in your faith been tested again, and how did you handle it together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 16, 'When you both face uncertainty or scarcity, do you tend to trust that you''ll have enough, or do you find yourselves wanting to hoard, as some of the Israelites did with the manna?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 17, 'When you faced a genuine need or crisis together, did you each assume the other knew what to do, or did you find yourselves stronger when you asked for help and support from those around you?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 18, 'When Jethro watched Moses wearing himself out by trying to handle everything alone, he saw what needed to change. What''s something you each are carrying by yourself that you could share with each other or ask for help with?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 19, 'When the people promised to obey God''s voice and keep his covenant, they spoke as one, confident in their answer. Looking back at your own marriage, where have you both made promises together that are proving harder to keep than you expected?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 20, 'When you both rest on the seventh day, what competes most for your attention, and what might change if you guarded that time more carefully together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 21, 'When you each think about your commitments to each other, what would it mean for you to choose to stay, not because you have to, but because you genuinely want to?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 22, 'When you think about what you owe each other in your marriage, where do you see yourself as the careful steward, and where do you sense you might be taking something for granted?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 23, 'When you think about the commands here to help your enemy''s animals, avoid false reports, and give the poor fair treatment, where do you find it hardest to do these things in your actual week, and what gets in your way?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 24, 'When you each commit to something together, what helps you actually follow through when it gets hard or when one of you feels uncertain?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 25, 'As you both think about God calling for willing gifts to build a place where he''d dwell among his people, what are you each pouring yourselves into together right now, and how is that shaping your home and marriage?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 26, 'As you both looked at this chapter about building the tabernacle with careful measurements and many pieces fitted together, what currently needs that kind of thoughtful, deliberate construction in your marriage or life together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 27, 'When you think about how carefully God specified every detail, the precise measurements, the materials, the way things fit together, what does that make you notice about how you each approach planning and preparing something important together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 28, 'When you think about Aaron bearing the names of all twelve tribes on his shoulders and heart as he approaches God, what person or responsibility in your own life feels like you''re carrying others'' needs or concerns close to your heart?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 29, 'This chapter describes a long, careful process of preparation and repeated actions before Aaron and his sons could serve. When you think about the roles each of you has taken in your marriage or faith, how much time and care have you given to preparing yourselves for them?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 30, 'As you each read about the repeated instructions to keep these sacred things, the incense, the oil, the basin, set apart and used only for their holy purpose, what in your own life or marriage do you need to protect from being used for something else?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 31, 'You''ve both been called to build something sacred together, your home, your marriage, your life. What work have you been doing this week, and when did you stop to rest from it together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 32, 'When the people grew anxious about Moses'' absence, they rushed to create something tangible to trust in. Where do each of you turn when you''re afraid or uncertain about what comes next, and how might that shape what you build your confidence on?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 33, 'After hearing that God won''t go with them as planned, Moses keeps asking for more of God''s presence and favor. What do you each long for most right now, and are you bringing those deeper longings to God together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 34, 'When Moses came down from meeting with God, his face shone so brightly that people were afraid to approach him. What in your lives together right now might need to be seen and shared with each other, even if it feels vulnerable to reveal?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 35, 'When you both think about a shared project or goal you''re working toward together, what moves each of you to contribute: is it the vision of what you''re building, or the joy of using what you already have?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 36, 'When you both look at how the craftsmen had to stop receiving offerings because there was already more than enough, what does that bring to mind about generosity or restraint in your own lives together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 37, 'As you read about Bezalel crafting each vessel with such care and precision, each one made to carry or hold something sacred, what do you each carry into your home and marriage that you want to treat with that same kind of attention?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 38, 'As you look at all the intricate details and materials that came together to build this sacred space, what are the ''building blocks'' you each bring to your marriage, and where do you see them actually being used?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 39, 'You both have read about craftspeople spending themselves on details, each stone placed, each bell and pomegranate sewn, all to create something set apart for God''s purpose. Where in your own lives right now are you pouring care and skill into something that matters to you both, even in small ways?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Exodus', 40, 'As you look at how carefully Moses set up each piece according to God''s instructions, what routines or rhythms in your own life together help you sense God''s presence, and where might you need to be more intentional?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 1, 'As you look at how God saw each part of creation as good, and then blessed the creatures to multiply and fill their spaces, what in your own life together feels like it''s still taking shape, waiting to be blessed and made fruitful?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 2, 'After reading about God resting on the seventh day and setting apart that time as holy, when do you each genuinely stop working and rest together, and what would change if you did?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 3, 'When you each heard the serpent''s question in this story, what lie have you most believed about God''s generosity or God''s word in your own life?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 4, 'When Yahweh asked Cain why his face had fallen, Cain didn''t answer or change course, and anger led him toward his brother instead of away from it. Each of you, what happens in your marriage when one of you feels rejected or overlooked, and how do you help each other rule over that hurt instead of letting it rule over you?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 5, 'What does it look like in your own lives right now to ''walk with God'' the way Enoch did, and how might becoming a parent or deepening your partnership change what that looks like for each of you?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 6, 'When you look at Noah standing out as righteous in a corrupt time, what does faithfulness to each other look like for you both in the middle of your own world?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 7, 'When Noah entered the ark with his family, everything outside was about to be destroyed while everything inside was preserved, what feels fragile or at risk in your lives right now, and how do you want to protect it together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 8, 'After being confined together for so long, Noah waited and watched for signs before stepping out into the new world. What are you both waiting to see right now, and how are you sensing when it might be time to move forward?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 9, 'You both have seen God''s covenant promise in the rainbow, yet you also see Noah''s failure and shame at the chapter''s end. When have each of you needed grace from your spouse after stumbling or being vulnerable?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 11, 'When you both work toward something together, like the people building Babel, how do you make sure you''re building something that actually brings you closer rather than pulling you apart?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 12, 'Abram left everything familiar at seventy-five and trusted God''s promise, yet later he feared for his life and asked Sarai to deceive Pharaoh. When have you each found yourselves both believing God and being afraid at the same time, and how did that show up between you?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 13, 'When you both have abundance and conflict follows, like Abram and Lot''s herdsmen, how do you choose between holding on and letting go?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 14, 'When Abram heard that Lot was taken, he quickly called on his allies and pursued to rescue him, yet when offered reward, he refused almost everything to keep his conscience clear. How do you each handle it when you help someone or solve a problem: do you find yourself wanting credit or recognition, or can you let it go?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 15, 'When Abram asks God ''How will I know that I will inherit it?'', he''s wrestling with doubt even as he''s been promised something extraordinary. Where do each of you find yourselves doubting God''s promises in your own life right now, and what would help you believe?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 16, 'When you both face a problem, how do you decide whose idea to follow, and what happens when that choice creates new tension between you?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 17, 'When God asks Abraham to do something difficult and unfamiliar, Abraham acts on it right away, even at his age. Where do you each sense God calling you to step forward in faith right now, even if the timing or the path feels uncertain?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 18, 'Abraham went to great lengths to welcome three strangers, and later he pleaded earnestly for mercy on a distant city. When have you each noticed the other doing something costly or brave for someone else''s sake, and what did that reveal to you about them?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 19, 'When Lot hesitated to leave and then negotiated for a smaller escape, and when his family didn''t take the warning seriously, what patterns do you each recognize in your own life, times when you''ve delayed responding to something that mattered, or when you''ve struggled to move together in the same direction?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 20, 'When you''re afraid about what might happen, what stories or explanations do you reach for to protect yourself, and how might that affect the trust between you?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 21, 'Sarah''s laughter of joy at Isaac''s birth is echoed later by tears and hard choices, yet God provides for what seems impossible. When have you both faced a moment recently where what you wanted and what was demanded of you felt at odds, and how did you work through it together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 22, 'When you''ve had to trust God with something precious or uncertain, what has helped you actually believe he would provide, the way Abraham did on the mountain?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 23, 'Abraham had to negotiate and pay a full price for a burial place, even though Ephron initially offered it freely. When has each of you had to insist on paying your own way, or struggle with accepting help that was offered to you?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 24, 'When you each consider a major decision in your marriage, how much do you trust that God is already working toward it, the way Abraham trusted his servant would find the right woman?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 25, 'As you read about Isaac and Rebekah''s sons growing up with such different gifts and each parent''s favorite, what does that remind you about where you each naturally turn toward your spouse, and whether that brings you closer together or pulls you apart?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 26, 'When you read about Isaac hiding the truth about Rebekah out of fear, and later about the conflict over the wells that kept pushing him to move, what season in your marriage have you faced difficulty because of fear or conflict, and how did you find your way through it?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 27, 'Where do you each feel like you might be tempted, like Rebekah was, to bend the rules to get what you think should happen in your life or marriage?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 28, 'Jacob made a vow to God at a lonely place, promising to give back a tenth of what God provided if he was kept safe on his journey. When you each face uncertainty or a big transition ahead, what would it mean for you both to remember that God is present with you there?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 29, 'Jacob''s love for Rachel seemed to make seven years of labor feel like only a few days, yet his preference for her left Leah feeling hated and unseen. When you look at your own marriage, where might one of you be pouring energy into something while the other feels overlooked or less valued?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 30, 'You both see here how Rachel and Leah each chase what they think will fix their deepest longing, and how that chase affects their marriage. What are you each pursuing right now that might be pulling you away from each other instead of toward each other?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 31, 'When you each look back on a time when you had to make a hard choice about leaving something or someone behind, did you confide fully in each other, or were there things you kept hidden from your spouse?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 32, 'When you face something that frightens you, how do you each tend to respond, do you move into action like Jacob sending gifts ahead, or do you first seek God''s help like his prayer, or something else entirely?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 33, 'After years apart, Jacob arranges his family carefully before meeting Esau, puts himself first in the line of vulnerability, and then asks Esau to slow his pace to match Jacob''s children and animals. What does this reveal about how you each tend to the vulnerable ones in your own life right now?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 34, 'When you each think about how Jacob''s sons responded to what happened to Dinah, what stirs in you about the difference between protecting someone you love and the way you go about it?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 35, 'When Jacob gathered his household to go to Bethel, he asked them to put away foreign gods and purify themselves. What are you both holding onto right now that might need to be released before you can move toward what God is calling you toward?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 37, 'When have you each felt jealousy or favoritism, either witnessing it between siblings, or feeling it in your own marriage, and what did it cost you?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 38, 'When have you each felt trapped by someone else''s broken promises or half-truths, and how did that shape what you did next?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 39, 'When you face pressure or temptation that could damage something you value, your home, your trust with each other, your character, what helps you stay faithful to what matters most?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 40, 'When you face hard times together, do you find yourselves more like Joseph, looking to see how you can help each other, or more like the cup bearer, forgetting about those who helped you when things improve?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 41, 'Joseph moved from the dungeon to ruling Egypt in a single day, then began his work of preparing for a future crisis he couldn''t control. When have you both faced a sudden change or opportunity that required you to step forward and do what was right, even without knowing how things would turn out?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 42, 'When the brothers realize they''re in danger and recall how they once ignored Joseph''s distress, what is keeping either of you from speaking up about something you''ve both been avoiding?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 43, 'When Jacob finally let Benjamin go, he said, ''If I am bereaved of my children, I am bereaved.'' What fear have you each had to release to God, and how did that letting go change things between you?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 44, 'When have you each had to speak up for someone you love, even when it meant admitting failure or asking for mercy?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 45, 'When Joseph told his brothers not to be angry with themselves, he pointed them toward something larger than their guilt: God''s purpose at work. As you both reflect this week, where do you each see God working through a hard season you''re walking through together, or have walked through?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 46, 'Jacob received God''s promise that he would go with him to Egypt and bring him back, yet he also made the long journey to see Joseph. When have you both moved forward together because of a promise, and what difference did it make to have each other along the way?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 47, 'Joseph secured everything for his family while managing a crisis for strangers, yet Jacob still worried about where he would be buried. What provision or security are you each most grateful for right now, and what are you still holding onto that you might need to release?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 48, 'When Jacob blessed Joseph''s sons in a way Joseph didn''t expect, Joseph tried to correct him. Where in your own life have you recently held firm to how you thought things should go, and what might shift if you let go?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 49, 'As Jacob blesses each son differently, according to who they actually are, what would you each want the other to notice and bless in you right now, in this season of your life together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Genesis', 50, 'Joseph grieves his father deeply, and later his brothers fear he will punish them now that their father is gone. When loss or change happens in your relationship, what old hurts sometimes surface that you thought were settled between you?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Hosea', 3, 'As you read about Hosea being called to love Gomer again despite her unfaithfulness, what does it stir in you both about how you show up for each other when trust has been broken?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Isaiah', 40, 'When you each read that God carries his flock gently and gives power to the weak, what weariness or struggle in your own life came to mind?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('John', 1, 'When you read about Andrew finding his brother Simon, or Philip finding Nathanael, who is someone in your life right now that you sense God inviting you both to point toward him?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('John', 2, 'When you both notice something missing or wrong in your shared life, how do you each tend to respond, and where might you need to trust each other more?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('John', 3, 'Nicodemus comes to Jesus with respect and curiosity, but struggles to understand what Jesus means by being born anew, whereas John the Baptist hears about Jesus gaining followers and responds with joy rather than doubt. Where do you each find yourself this week, wrestling with something you don''t yet understand, or celebrating something God is doing in someone else''s life?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('John', 4, 'The woman at the well left her water pot behind and told her whole city about Jesus, and that ordinary testimony changed many minds. What has each of you noticed about someone whose simple story or life has quietly shifted how you think or believe?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('John', 5, 'When the man at the pool made excuses about why he couldn''t be healed, Jesus didn''t scold him but asked if he wanted to be well, then acted. Where in your marriage do you find yourselves stuck in a pattern, and what would it look like to move differently together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('John', 6, 'When the crowd followed Jesus seeking another meal after the feeding of five thousand, he told them they were looking for the wrong thing. What are you both tempted to pursue this week that feels urgent, but might be keeping you from what actually matters?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('John', 7, 'When have you each felt pressured to prove yourself or show results before you were ready, and how did that differ from what Jesus modeled with his brothers?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('John', 8, 'When you read about the woman in the middle of the crowd, and then Jesus''s words about being the light of the world, what does it stir in each of you about how you want to treat each other when one of you has stumbled or failed?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('John', 9, 'When the man born blind kept simply telling what he knew, ''I was blind, now I see'', without needing to understand everything about how it happened, what in your own life are you both trying to figure out before you trust it?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('John', 10, 'When Jesus says his sheep know his voice and won''t follow a stranger''s, what voices compete for your attention in your daily life, and how do you help each other recognize which ones to follow?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('John', 11, 'When Martha and Mary each say to Jesus, ''If you would have been here, my brother wouldn''t have died,'' they''re expressing pain in the midst of their trust in him. What disappointment or unmet expectation have you each been carrying in your faith, and how are you holding both the hurt and the hope together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('John', 12, 'Mary poured out what was precious to her while others questioned the cost, and later some rulers believed but stayed silent for fear of what others would think. Where do you each feel torn between giving something costly or speaking something true, and what holds you back?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('John', 13, 'Jesus washed his disciples'' feet knowing one would betray him, and afterward gave his new commandment to love one another. When have you each shown love to the other even when trust felt difficult or uncertain?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('John', 14, 'When Jesus tells his troubled disciples not to let their hearts be troubled, what''s weighing on each of you right now that could use that kind of peace and reassurance from each other?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('John', 15, 'When Jesus says the branches that bear fruit are pruned so they may bear more, what kind of pruning or difficult season is each of you experiencing right now, and how do you see it shaping what you''re becoming together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('John', 16, 'When you each face something hard this week, where do you turn to remember that sorrow doesn''t have the final word?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('John', 17, 'Jesus prays that his followers will be kept from evil while still sent into the world, and that they will be one as he and the Father are one. Where do each of you feel most pulled between staying separate from the world and being sent into it?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('John', 18, 'When you''re facing something difficult together, how do you each tend to respond: like Peter, who acted impulsively and then denied what mattered, or like Jesus, who stayed honest about who he was even when it cost him?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('John', 19, 'As you watch others around Jesus stand firm or step back in this moment, where do you find yourself hesitating to be known as his, and what might change that for each of you?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('John', 20, 'In this chapter, people encounter the risen Jesus in very different ways, some see evidence first and believe, Mary recognizes him by name, Thomas demands proof before he''ll trust, so when you think about what it takes for each of you to truly believe something important, what comes to mind?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('John', 21, 'When Jesus asks Peter three times about his love, and then calls him to follow, Peter''s first instinct is to look over at another disciple and ask about him instead. Where do you each feel the pull to compare your calling or path with someone else''s, and what might it cost you both?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Joshua', 1, 'Joshua steps into leadership after Moses, and the people commit to following him into an uncertain crossing. Where do each of you feel called to lead or follow in this season of your life together, and what would courage look like for you both?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Joshua', 2, 'Rahab risked everything to protect these strangers based on what she''d heard about God''s faithfulness. When have each of you taken a risk for someone else, and what gave you the courage to do it?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Joshua', 3, 'You both are about to step into something you''ve never faced before, just as Israel stood at the Jordan. Where in your life right now do you need to follow even though you can''t see the whole path ahead, and how might you support each other through that crossing?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Joshua', 4, 'What''s a moment from your life together that you want to make sure you tell your children about, and how might you keep that story alive between now and then?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Joshua', 5, 'The people had to go through a painful ritual before they could move forward into what God promised them. What might need to happen between you two before you can step into something you''ve been waiting for?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Joshua', 6, 'What''s something you''ve felt called to do together as a couple, even though the path to it seemed unclear or required you to wait and trust before you could move forward?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Joshua', 7, 'When you each think of something you''ve hidden or kept secret from the other, what makes it hard to bring it into the open like Achan finally did?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Joshua', 8, 'Joshua had to carry out God''s instructions exactly, down to the details of the ambush and the altar afterward. Where in your own life right now do you each find it hardest to follow through completely on something you''ve committed to, rather than taking shortcuts?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Joshua', 9, 'When have you each made a decision quickly without stepping back to pray about it first, and what did you learn from how that turned out?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Joshua', 10, 'When the people of Gibeon called out to Joshua in their fear, he answered immediately without hesitation. What calls for help from each other do you sometimes delay responding to, and what might change if you moved as quickly as Joshua did?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Joshua', 11, 'When Joshua faced enemies far more numerous than his own forces, God told him not to be afraid and gave him the victory. What worry has felt overwhelming to each of you lately, and how might you encourage one another to trust differently about it?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Joshua', 12, 'As you look at this long list of conquered cities and kings, what''s one area of your life where you and your husband are still waiting to see God''s promised victory come through?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Joshua', 14, 'Caleb waited forty-five years to claim what God had promised him, and at eighty-five he still felt strong enough to fight for it. When you look at a promise or dream in your marriage that has been waiting a long time, do you still have the courage and energy to pursue it together, or has doubt worn that away?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Joshua', 16, 'Where in your lives together do you settle for less than complete victory, accepting compromise instead of pushing through to what God promised you?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Joshua', 18, 'Joshua grew impatient with the delay, asking the seven tribes how long they would put off claiming what had been promised to them. What promises or plans in your own life have you been slow to step into, and what might be holding each of you back?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Joshua', 20, 'When you''ve made a serious mistake, do each of you tend to hide or to speak up and explain what really happened, knowing the difference between an accident and neglect?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Joshua', 22, 'The eastern tribes built an altar not to worship differently, but to prove to future generations that they belonged to God''s people. When you each think about your marriage and your separate lives, where do you worry that distance or misunderstanding might make the other question your commitment to the things you share?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Joshua', 23, 'Joshua reminds Israel that what God promised has come true, and warns them that what they do next matters just as much. What promises have you each seen God keep in your marriage or life, and how does that shape what you''re choosing to hold onto right now?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Joshua', 24, 'When Joshua asks the people to choose whom they will serve, and they promise they will serve God, what choice or commitment are you both facing right now where you need to be honest about what you actually intend to do?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Judges', 1, 'When you look at the tribes who completed their task versus those who settled for living alongside their enemies, what are you currently choosing to finish rather than compromise on in your life together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Judges', 2, 'When you each think about what you''ve let into your life instead of what God has asked of you, what patterns do you notice repeating, and where do you need each other''s help to turn back?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Judges', 3, 'When you think about how Israel kept returning to the same patterns of turning away and then crying out for help, what habits or rhythms do you both notice repeating in your own life together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Judges', 4, 'When have you each felt uncertain about a calling or decision, the way Barak did before going into battle, and how did your spouse''s willingness to stand with you make a difference?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Judges', 5, 'Deborah sang about people who rose up willingly while others stayed home, and Jael acted decisively when called to do hard things. Where do you each see yourselves right now, in this season of your marriage, stepping forward into something difficult, or holding back, and what would help you move?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Judges', 6, 'Gideon kept asking for signs even after God spoke to him directly, and he hid his obedience from his own household out of fear. Where do you each find yourselves hesitating to act on what you believe, either from doubt or from fear of what others might think?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Judges', 7, 'When Gideon heard the enemy soldier''s dream and felt his courage return, what small reassurance has each of you needed recently to take the next step together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Judges', 8, 'When someone doubts you or refuses to help when you need it most, how do you typically respond once you''ve succeeded, and what might that reveal about where your heart was really focused?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Judges', 9, 'When you''ve chosen someone or something to follow, have you ever stopped to ask whether it was actually worthy of your trust, or did the momentum and the crowd''s approval carry you along?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Judges', 10, 'When you both turn away from what matters most, what does it take to bring you back together, and are you willing to do it?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Judges', 11, 'Jephthah was rejected by his own family but then called on when they needed him most. When has each of you been needed by someone who had previously hurt you, and what did you choose to do?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Judges', 12, 'When you each felt left out or unsupported by the other this week, what might it have cost you to ask for help anyway instead of acting alone?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Judges', 13, 'When the angel first appeared to Manoah''s wife, she shared the news with her husband, and he immediately asked God to send the angel back so they could learn how to raise their son together. What does it look like for you both to seek guidance together about something that matters to your family?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Judges', 14, 'When have you each kept something important hidden from the other, thinking you were protecting yourself or keeping things separate, and what might that have cost you both?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Judges', 15, 'When you''ve been hurt or wronged, how do you each tend to respond, do you strike back right away, or do you sometimes act in ways that pull others into the conflict with you?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Judges', 16, 'Samson kept testing Delilah even after she repeatedly pressed him for his secret, until finally his resistance wore down and he told her everything. Where in your own life do you find yourselves wearing down under pressure, and how might you be honest with each other about it before that happens?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Judges', 17, 'When you both look at how Micah tried to secure blessing, first through stolen money, then through objects and hired priests, what are you each trusting in right now to protect your marriage or your life together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Judges', 18, 'When you both face a choice that feels urgent or exciting, how do you check whether you''re moving toward something good or just being swept along by momentum?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Judges', 19, 'When the Levite refused his father-in-law''s repeated invitations to stay longer, he was trying to get home, yet the delay in leaving led to terrible danger: where do you each see stubbornness or rushing in your own week, and how might pausing to listen to someone who cares about you change things?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Judges', 20, 'When you each read how the Israelites went back to God after their first two defeats, asking again and again before they found victory, what makes you think about returning to God together when something in your own lives isn''t working the first time?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Judges', 21, 'Both of you have made promises that created real problems between you or with others, and then scrambled to fix the mess in ways you''re not proud of. When have each of you done that, and what would you do differently now?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Leviticus', 1, 'When you think about giving something to God, what does it cost you, and how do each of you experience that cost differently?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Leviticus', 2, 'When you bring something to God, what details matter most to you, the ingredients themselves, the way you prepare them, or something else entirely?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Leviticus', 4, 'When you sin without meaning to, how do you actually know you''ve been forgiven, and what does that look like in your marriage?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Leviticus', 5, 'When you realize you''ve done something wrong, whether you stayed silent when you should have spoken, made a careless promise, or broken a rule without meaning to, what keeps you from coming clean with each other and with God?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Leviticus', 6, 'When you''ve wronged someone, what usually stands in the way of you making it right, and what would it take for you both to move toward repair together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Leviticus', 7, 'When you make an offering or give something to God, what time limits or conditions do you put on your generosity, and what might that reveal about how you both approach sacrifice together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Leviticus', 8, 'Aaron and his sons were set apart through oil, blood, garments, and a full week of staying close to the place of meeting. What does it look like in your own life when you both step back from everything else to focus on something sacred between you?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Leviticus', 9, 'When you each see God show up in a visible, unmistakable way in your life or marriage, what does that moment usually call out of you, and is it the same for both of you?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Leviticus', 10, 'Aaron stayed silent when his sons died, then later spoke up to Moses about whether he should have eaten the sin offering that day. When have you each found it hard to know whether to stay quiet or to speak in a moment of grief or confusion?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Leviticus', 11, 'As you both think about the careful distinctions God draws in this chapter between what is clean and unclean, where do you find yourselves making similar distinctions in how you spend time together, and do those choices feel purposeful or do they drift?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Leviticus', 13, 'When you''ve both faced something uncertain or uncomfortable about your health or body, how did you decide when to seek help, and how did waiting or knowing change things between you?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Leviticus', 14, 'When you''ve been through something that required time, steps, and the help of others to move past it, what did that process teach each of you about healing?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Leviticus', 15, 'When you read all these rules about cleansing and waiting until evening, what comes to mind about the rhythms of rest and restoration in your own week together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Leviticus', 16, 'When you each read about Aaron setting aside one day a year to confess all the people''s sins and send them away, what burdens have you been carrying into this week that might be worth laying down together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Leviticus', 17, 'When you think about bringing something precious to God rather than handling it on your own, what comes to mind in your life right now, and how does each of you approach that differently?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Leviticus', 18, 'God opens this passage by telling Israel not to follow the practices of the nations around them, but instead to keep his ordinances and live by them. As you look at your own life together, where do you feel pulled to do what everyone else does rather than what you believe is right?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Leviticus', 19, 'This chapter weaves together respect for parents, honesty in dealings, care for the poor and foreigner, and truthfulness in your words and judgments. Where do you each sense God calling you to live more carefully in one of these areas, right now in your marriage and daily life?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Leviticus', 20, 'Reading this chapter''s call to ''sanctify yourselves therefore, and be holy,'' what patterns or habits in your own life feel like they''re drawing you away from what you sense God wants for you both?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Leviticus', 21, 'When you think about the people and roles that matter most in your lives together, what standards or expectations do you hold for yourselves, and how does the weight of those expectations shape how you show up for each other?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Leviticus', 22, 'When you bring something to God, whether through your church, your prayers, or your time together, do you find yourselves offering what costs you something, or what''s convenient?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Leviticus', 23, 'Looking at how these festivals mark time throughout the year, seasons of rest, remembrance, and gathering, what rhythms or regular practices help you both stay connected to what matters most?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Leviticus', 24, 'As you look at your week ahead, where do you need to tend something faithfully like the lamp that burned continually, and where might you need to be more careful with your words?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Leviticus', 25, 'When you think about the rhythm of work and rest woven through this year of Jubilee, what would it look like for you both to practice letting something go every seven years, whether that''s a pattern, a possession, or a worry?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Leviticus', 26, 'When you think about what leads to flourishing versus what leads to hardship in your own lives, how do you see the connection between your choices and what follows?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Leviticus', 27, 'When you think about what you''ve dedicated to God, your time, resources, or commitments, how do you each handle the temptation to take some of it back or swap it for something easier?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Luke', 15, 'When you each think about the father''s welcome or the older son''s anger in this story, whose response feels more like where you are right now in your faith or your marriage?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Mark', 4, 'When you think about what''s been planted in your marriage this week, words, attention, worries, hopes, what''s actually taking root and growing between you?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Matthew', 5, 'When you read that anger at a brother deserves judgment, or that lust in the heart is already adultery, where do you each feel most convicted in your own life or in how you treat each other?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 1, 'What leaders or people in your life do you each trust to help you see things clearly, the way Moses relied on the twelve tribal heads to count and know the people?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 2, 'Each of you has a place in your marriage and in the groups you belong to, just as each tribe had its location in the camp. How do you both feel about where you stand right now, and what role you''re meant to play together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 3, 'When you look at how carefully the Levites were organized by family and assigned specific duties around the tabernacle, what areas of your life together feel clear and ordered, and where do you sense you need better structure or clarity about your roles?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 4, 'Each of you has different work to do, different burdens to carry, different responsibilities like the Kohathites, Gershonites, and Merarites had. Where do you each feel most needed right now, and are you both clear about what that looks like?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 5, 'When doubt or suspicion has crept into your relationship, how have you each chosen to address it: by bringing it into the open, or by letting it fester in silence?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 6, 'When you each think about a commitment you''ve made together or individually, how has keeping that commitment, even through the hard or inconvenient parts, shaped who you are becoming?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 7, 'Each of the twelve leaders brought the exact same offering, one after another over twelve days. When you both give or serve, do you find yourselves comparing what each of you does, or can you offer what''s yours without measuring it against the other?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 8, 'The Levites were set apart through cleansing and preparation, then given a specific role and season of service. Where do you each feel called to use your gifts right now, and how might your marriage itself be part of that calling?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 9, 'When have you each felt unable to participate in something important to you, and how did you handle waiting or finding another path forward, as those unclean men did?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 10, 'When Israel broke camp, each tribe moved in a specific order and knew where they belonged, yet Moses still asked Hobab to guide them through the wilderness. Where in your own life do you both follow a clear direction, but still need someone else''s particular knowledge or perspective to get there well?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 11, 'When you both feel the weight of life''s complaints and needs pressing in, do you tend to shoulder it alone like Moses did, or do you reach out and share the burden with each other?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 12, 'When you find yourselves critical of each other, what usually comes first, the real concern beneath it, or the hurt of feeling left out or undervalued?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 14, 'When fear or doubt creeps into your life together, do you find yourselves more like those who panic and want to turn back, or more like Caleb and Joshua, who trust despite the danger?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 15, 'When you read about the fringes on garments meant to help people remember God''s commands throughout their day, what small visible reminder or habit have you each found helpful in your own life to stay connected to what matters most?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 16, 'When you each read how Korah and the others grew discontent with the place they''d been given, did you recognize any restlessness or comparison happening in your own lives right now?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 17, 'When you each think about areas where God has already shown his faithfulness to you both, what doubts about his leadership still creep in?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 19, 'When you think about the careful steps described here for dealing with death and making things clean again, what grief or loss have you each carried that still needs tending, and how might you help each other attend to it?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 20, 'When you both face a hard situation together, do you tend to blame each other or turn toward God together like Moses and Aaron did at the tent?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 21, 'When you felt most discouraged or doubtful this past week, what helped you turn back toward trust, the way the people turned to Moses and the bronze serpent?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 22, 'When have you each felt torn between what someone wanted from you and what you sensed God was asking of you, and how did you handle that pull?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 23, 'When Balaam kept blessing Israel even though Balak wanted him to curse them, he said he could only speak what God put in his mouth. Have either of you faced a time when you couldn''t do what someone wanted because of something you believed, and how did that feel between you two?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 24, 'When Balaam realized he couldn''t speak anything except what God wanted him to say, he accepted it and went home. Where in your own life is God asking you both to surrender your agenda and simply speak or do what he wants instead?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 25, 'Where do you each feel pulled toward something that feels good in the moment but might separate you from what you say matters most to you?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 26, 'As you both think about the names and families listed here, each person counted and known by God, what names or relationships matter most to you right now, and why?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 27, 'The daughters of Zelophehad spoke up for what mattered to them and their family''s future, and Moses listened and brought their case to God. Is there something you''ve both been hesitant to name or ask for, together or apart, that might be worth speaking up about?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 28, 'When you look at how the Israelites were called to worship regularly, morning and evening, weekly, monthly, and throughout the year, what rhythms of togetherness do you two want to protect in your own life?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 29, 'Throughout these seven days of festival, the offerings change day by day, from thirteen bulls on the first day down to seven on the seventh. What rhythms or patterns in your own life feel important to honor together, and how do you each experience them when things shift or diminish?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 30, 'When you each make a commitment, whether to each other or to God, how do you handle it if the other person seems to hesitate or object rather than speak up clearly?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 31, 'When you''ve come through something difficult or costly together, how do you decide what to set aside as an offering of gratitude, and what to keep moving forward with?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 32, 'When you first saw what you wanted in life, did you think about how it might affect the whole community you''re part of, or did you mostly think about whether it would work for you both?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 33, 'Looking at this long record of stops and starts, camps and moves, where do you each sense you are right now in your own journey together, and what might you need at this particular stopping place?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 34, 'As you look at the specific boundaries God set for the promised land, and the careful naming of leaders to distribute it fairly, what clear limits or structure have you each felt God calling you to establish in your own lives right now?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 35, 'When you think about the cities of refuge in this chapter, places where someone who caused harm could be protected while waiting for a fair judgment, what situations in your own life require you to step back and wait for clearer understanding before reacting?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Numbers', 36, 'The daughters of Zelophehad had to marry within their own tribe to keep their family''s inheritance intact. When you''ve had to choose between what you wanted and what protected something important to your family, how did you navigate that together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Proverbs', 3, 'When you think about kindness and truth binding your lives together, or about holding back good that you could offer each other, what comes to mind from your week?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Proverbs', 27, 'Which kinds of honesty between you feel harder to give or receive, the direct rebuke or the kind words that might go unspoken?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 1, 'When you think about the counsel and company you''re letting into your lives together, what are you meditating on day and night, and is it nourishing you both?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 16, 'When you think about the ''portion and cup'' the psalmist describes as assigned to you, what comes to mind, and where do you each find your deepest contentment right now?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 23, 'When has each of you felt led to a place of rest this week, and where do you each most need to be guided right now?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 27, 'When you each think of the one thing you most want from God right now, how does it compare to what the writer asks for in this psalm, and what does that difference tell you about where each of you is in your faith this season?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 30, 'Has there been a time when you both felt secure, only to have circumstances shake that confidence? What brought you back to solid ground?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 34, 'When you each think about what the psalmist describes, crying out and being heard, being delivered from fear, tasting that God is good, what situation between you this week has left one of you feeling unheard or afraid, and how might you turn toward each other with that same attention?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 37, 'When you find yourselves frustrated by someone else''s success or worried about injustice in the world, what does it look like for you both to ''cease from anger'' and trust instead of fretting?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 40, 'The psalmist moves from celebrating God''s rescue to feeling overwhelmed by guilt and asking for help. Where do you each find yourself this week, and what would it mean to ask for help the way the psalmist does?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 42, 'Where do you each feel most parched right now, and where have you noticed God''s presence or help, even small, this past week?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 46, 'When you face something that shakes you this week, whether it''s news, a conflict, or uncertainty, how do you each tend to respond, and where do you actually find steadiness in those moments?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 51, 'When you each think about a weight you''re carrying right now, what would it mean to bring that into the open with God, the way this psalm does, rather than hiding it?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 56, 'When you feel attacked or misunderstood this week, what would it look like for each of you to turn that moment into trust rather than fear?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 62, 'When you look at what''s been destabilizing or shaking you both lately, the lies spoken about you, the people working against you, the comparisons you can''t help making, where do you actually find yourselves looking for solid ground?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 63, 'When you think of seeking God the way this psalm describes, with real longing, in ordinary moments like lying in bed at night, what does that actually look like for each of you right now, and where do you feel most parched?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 73, 'When you look at what others around you seem to have or achieve, what tempts you to question whether your own faithfulness actually matters?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 84, 'The psalmist describes a journey through hard places that become sources of blessing, and a preference for even small belonging in God''s presence over comfort elsewhere. What hard season in your life or marriage might God be inviting you to see differently, and how could you support each other in that shift?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 90, 'The psalm speaks of our days passing quickly and asks God to teach us to count our days and gain a heart of wisdom. When you look at how you''re each spending your time these days, what would counting your days differently help you notice or change between you?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 91, 'When you each read about dwelling in God''s refuge and being guarded through danger, what fears or uncertainties are you carrying right now that you''d like to bring into that shelter together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 103, 'The psalmist speaks of remembering God''s benefits and not forgetting them, even when life feels fleeting as grass and flowers. What have you each experienced this week that you might easily overlook without stopping to remember it together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 116, 'When you''ve felt delivered from trouble like the psalmist describes, how have you each shown gratitude for it, and what kept you from forgetting that rescue over time?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 118, 'When you read how the psalmist called out in distress and was answered with freedom, what distress are you each carrying this week that you wish to bring before God together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 121, 'When you think about your coming and going this week, where do you actually turn first when you need help or protection, and what would it look like to turn there first instead?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 126, 'When have you each experienced a shift from sorrow to joy, and what seed were you planting during the hard part?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 130, 'When have you each found yourself crying out from a low place this week, and what small sign of God''s faithfulness are you waiting to see?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 131, 'When you look at your week together, where has one of you been reaching for something beyond your grasp, and how might stilling your soul instead bring you peace?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 133, 'When you think of the unity you share as a couple, what feels most like that precious oil or dew in your life together right now, and where do you sense the blessing flowing from it?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 138, 'When you called out in the middle of trouble, how did you experience God''s answer, and what strength did you find together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 139, 'Where do you each feel most hidden or alone, and how might it change things to know that even there, you''re fully known and held together?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 145, 'When you think about the ways God has been gracious and merciful to you both this past week, what''s one moment you''d want to pass on to the next generation the way this psalm describes?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Psalm', 146, 'When you look at where you''re placing your hope this week, between the two of you, what feels most real to trust: the help of people and powers around you, or God''s faithfulness?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Romans', 8, 'When you look at the struggles or frustrations you''re each carrying right now, where do you find yourself setting your mind: on the things of the flesh, or on the things of the Spirit?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Ruth', 1, 'When has one of you stayed with the other through a season of loss or grief, even when it would have been easier to go your separate way?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Ruth', 2, 'When you each look back at this past week, where did you notice someone going out of their way to show you kindness or protection, the way Boaz did for Ruth?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Ruth', 3, 'Naomi encouraged Ruth to seek rest and security by taking a bold step forward, and Ruth did what she was asked. When have you each needed to trust someone''s guidance in your own life, and how did that trust shape what happened between you?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
insert into public.passage_prompts (book, chapter, prompt) values ('Song of Solomon', 8, 'What does it feel like for each of you to be chosen and set apart by your beloved, the way these lovers speak of being marked and kept?')
  on conflict (book, chapter) do update set prompt = excluded.prompt;
